"""第27回、既存992件の固定支持と源励振の原因分離を事前登録する。"""
from pathlib import Path
import sys,ast,json,hashlib,shutil,os
ROOT=Path(__file__).resolve().parent;REPO=ROOT.parents[2]
PREVIOUS=ROOT/'campaigns/nas-world-excitation-audit-20261008-v1'
HERE=ROOT/'campaigns/nas-support-excitation-audit-20261008-v1'
PERIOD=ROOT/'campaigns/nas-source-period-audit-20261008-v1'
