sys.path[:0]=[str(PREVIOUS),str(ROOT)]
from temporary_storage import ManagedStorageBudget as Budget
from budget import read,digest,encode
NAME='support-excitation-audit-v1'
SOURCES=json.loads("{\"paths.py\":\"\\\"\\\"\\\"固定有声支持と励振診断の固定位置。\\\"\\\"\\\"\\nfrom pathlib import Path\\nimport sys\\nHERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1];REPO=ROOT.parents[2]\\nsys.path.insert(0,str(ROOT))\\nfrom budget import read,digest,encode\\nfrom temporary_storage import ManagedStorageBudget as Budget\\nNAME='support-excitation-audit-v1'\\nPERIOD=ROOT/'campaigns/nas-source-period-audit-20261008-v1'\\nWINDOW=ROOT/'campaigns/nas-hts-window-audit-20261008-v1'\\nWORLD=ROOT/'campaigns/nas-world-excitation-audit-20261008-v1'\\nCROSS=ROOT/'campaigns/nas-cross-factor-failure-audit-20261008-v1'\\nPYTHON=REPO/'research/experiments/autonomous-speech-synthesis/.venv-eval/bin/python'\\n\",\"worker.py\":\"\\\"\\\"\\\"全992の固定支持を保持し、励振源・測定欠測・未知を診断する。\\\"\\\"\\\"\\nfrom paths import *\\nimport argparse,io,sys,os,re\\ndef libraries():\\n    import tempfile\\n    assert Path(tempfile.gettempdir()).resolve()==Path(os.environ['TMPDIR']).resolve()\\n    sys.path[:0]=[str(PERIOD/'runtime-bundle'),str(PERIOD/'runtime-bundle/packages-v2')]\\n    import numpy as np\\n    return np\\ndef hts(job):\\n    np=libraries();import observer\\n    b=Budget();records=read(HERE/'protocol.json')['records'];results=[]\\n    for item in records:\\n        if item['cohort']!='nas-vocoder-f0' or not item['method'].startswith('hts'):continue\\n        target=HERE/'new-hts-diagnostic'/(item['id']+'.json')\\n        if target.exists():\\n            d=read(target);assert digest(REPO/d['trace_path'])==d['trace_sha256'];results.append(dict(id=item['id'],path=str(target.relative_to(REPO)),sha256=digest(target)));continue\\n        assert digest(REPO/item['record'])==item['record_sha256'] and digest(REPO/item['parameters'])==item['parameters_sha256']\\n        old=read(REPO/item['record']);assert old['meta']['output_gain']==.25\\n        with np.load(REPO/item['parameters']) as a:params=[a[k].copy() for k in ['mcp','lf0','lpf']]\\n        data,traces,meta=observer.observe(params,old['meta']['settings'],params[0][0],False)\\n        assert meta['sha256']==item['wave_sha256']==digest(REPO/item['wave'])\\n        tp=HERE/'new-hts-trace'/(item['id']+'.npz');buf=io.BytesIO();np.savez_compressed(buf,**traces)\\n        if tp.exists():\\n            with np.load(tp) as a:assert set(a.files)==set(traces) and all(np.array_equal(a[k],v) for k,v in traces.items())\\n        else:b.write(tp,buf.getvalue(),job)\\n        d=dict(id=item['id'],trace_path=str(tp.relative_to(REPO)),trace_sha256=digest(tp),old_wave_sha256=item['wave_sha256'],\\n            wave_byte_exact=True,trace_kind='HTS周期・counter・発生前pulse。LPF後の周期成分/知覚pitchは未資格。',meta=meta)\\n        b.write_data(target,encode(d),job);results.append(dict(id=item['id'],path=str(target.relative_to(REPO)),sha256=digest(target)))\\n        print('HTS追加観測',len(results),'/96',flush=True)\\n    assert len(results)==96\\n    b.save(HERE/'new-hts-manifest.json',dict(rows=results,expected=96,all_wave_byte_exact=True,new_audio_saved=0),job)\\ndef diagnosis(job):\\n    np=libraries();from pulse_ground import ground\\n    b=Budget();protocol=read(HERE/'protocol.json');traces={}\\n    for x in read(PERIOD/'diagnostic-manifest.json')['rows']:\\n        assert digest(REPO/x['path'])==x['sha256'];d=read(REPO/x['path']);traces['nas-mcp-postfilter/'+d['id']]=d\\n    for x in read(HERE/'new-hts-manifest.json')['rows']:\\n        assert digest(REPO/x['path'])==x['sha256'];d=read(REPO/x['path']);traces[d['id']]=d\\n    assert len(traces)==224 and read(WORLD/'aggregate-summary.json')['unknown_actual_excitation_cases']==768\\n    cohorts={}\\n    for name in protocol['cohorts']:\\n        p=read(ROOT/'campaigns'/(name+'-20261008-v1')/'protocol.json');cohorts[name]={r['id']:r for r in p['rows']}\\n    results=[]\\n    for item in protocol['records']:\\n        target=HERE/'diagnostic'/(item['id']+'.json')\\n        if target.exists():\\n            assert read(target)['source_record_sha256']==item['record_sha256'];results.append(dict(id=item['id'],path=str(target.relative_to(REPO)),sha256=digest(target)));continue\\n        assert digest(REPO/item['record'])==item['record_sha256'] and digest(REPO/item['parameters'])==item['parameters_sha256']\\n        old=read(REPO/item['record']);m=old['measurement'];row=cohorts[item['cohort']][item['row_id']]\\n        with np.load(REPO/item['parameters']) as a:\\n            lf0=a['lf0'][:,0].copy();duration=a['duration'].copy()\\n        assert np.array_equal(duration,np.asarray(old['meta']['duration']))\\n        bounds=np.r_[0,np.cumsum(duration)];assert bounds[-1]==len(lf0)\\n        with np.load(REPO/item['dio']) as a:f0=a['f0'].copy();times=a['times'].copy()\\n        assert digest(REPO/item['dio'])==item['dio_sha256']\\n        local={x['index']:x for x in m['local']}\\n        assert list(local)==m['support']\\n        actual=traces.get(item['id']);period=pulse=None;window={}\\n        if actual:\\n            tp=REPO/actual['trace_path'];assert digest(tp)==actual['trace_sha256']\\n            assert actual.get('old_wav_sha256',actual.get('old_wave_sha256'))==item['wave_sha256']\\n            with np.load(tp) as a:period=a['period'].copy();pulse=a['pulse'].copy();counter=a['counter_before'].copy()\\n            assert len(period)==len(lf0)*240 and np.array_equal(pulse.astype(bool),(period>0)&(counter+1>=period))\\n            for width in [20,40,60]:window[width]=ground(np,period,pulse,times,width)\\n        intervals=[]\\n        for index in m['support']:\\n            lo,hi=int(bounds[index*5]),int(bounds[(index+1)*5]);mask=(times>=lo*.005)&(times<hi*.005)\\n            values=f0[mask&(f0>=70)&(f0<=800)];n=int(mask.sum())\\n            supported=bool(n>0 and len(values)>=3 and len(values)>=n*.5)\\n            assert n==local[index]['interval_frames'] and len(values)==local[index]['voiced_frames'] and supported==local[index]['support_complete']\\n            missing=index in m['missing_support'];assert missing==not_supported(supported)\\n            phone=re.search(r'\\\\-([^+]+)\\\\+',row['full_context_labels'][index]).group(1)\\n            drive=int((lf0[lo:hi]>-1e9).sum())\\n            d=dict(index=index,phone=phone,start_frame=lo,end_frame=hi,duration_ms=(hi-lo)*5,\\n                old_clock_frames=n,old_DIO_voiced_frames=len(values),old_DIO_support_complete=supported,\\n                old_fixed_support_missing=missing,driving_voiced_frames=drive,driving_total_frames=hi-lo,\\n                driving_state='unvoiced' if drive==0 else ('fully_voiced' if drive==hi-lo else 'partly_voiced'),\\n                drive_is_not_actual_excitation=True)\\n            if actual:\\n                segment=period[lo*240:hi*240];count=int(pulse[lo*240:hi*240].sum())\\n                category='source_unvoiced' if not (segment>0).any() else ('no_pulse_in_interval' if count==0 else ('fewer_than_four_pulses' if count<4 else 'pulse_present_acoustic_ambiguity'))\\n                d.update(actual_source_state=category,actual_periodic_source_samples=int((segment>0).sum()),actual_sample_count=len(segment),actual_pulse_count=count,\\n                    no_source_pulse_does_not_exclude_filter_ringing=True,pulse_does_not_guarantee_periodic_energy_or_perceived_voicing=True)\\n                wd={}\\n                for width,(k,h,c) in window.items():\\n                    positive=mask&((k==4)|(k==5));accepted=(f0>=70)&(f0<=800)\\n                    correct=positive&accepted&(abs(12*np.log2(np.maximum(f0,1)/np.where(np.isfinite(h),h,1)))<=1)\\n                    wd[str(width)]=dict(stable=int((mask&(k==4)).sum()),dynamic=int((mask&(k==5)).sum()),\\n                        boundary=int((mask&(k==1)).sum()),source_unvoiced=int((mask&(k==2)).sum()),\\n                        insufficient_pulses=int((mask&(k==3)).sum()),edge=int((mask&(k==0)).sum()),\\n                        DIO_missing_on_pulse_targets=int((positive&~accepted).sum()),DIO_correct_on_pulse_targets=int(correct.sum()),\\n                        diagnostic_mean_pulse_rate_not_perceived_pitch=True)\\n                d['pulse_window_counts']=wd\\n            else:d.update(actual_source_state='WORLD_unknown_compatibility_nonpass',actual_pulse_count=None,actual_periodic_source_samples=None)\\n            intervals.append(d)\\n        assert [d['index'] for d in intervals if d['old_fixed_support_missing']]==m['missing_support']\\n        result=dict(id=item['id'],cohort=item['cohort'],row_id=item['row_id'],condition=item['condition'],method=item['method'],length=row['length'],\\n            source_record_sha256=item['record_sha256'],wave_sha256=item['wave_sha256'],all_fixed_support_intervals=intervals,\\n            fixed_support_count=len(m['support']),missing_support_count=len(m['missing_support']),source_trace_sha256=actual['trace_sha256'] if actual else None,\\n            actual_source_known=actual is not None,old_support_and_DIO_exact=True,causal_or_perceptual_claim=False,old_qualification_unchanged=True)\\n        b.write_data(target,encode(result),job);results.append(dict(id=item['id'],path=str(target.relative_to(REPO)),sha256=digest(target)))\\n        if len(results)%32==0:print('固定支持診断',len(results),'/992',flush=True)\\n    assert len(results)==992\\n    b.save(HERE/'diagnostic-manifest.json',dict(rows=results,expected=992,actual_source_known=224,WORLD_source_unknown=768,old_DIO_support_exact=True,quality_goal_completed=False),job)\\ndef not_supported(value):return not value\\ndef main():\\n    p=argparse.ArgumentParser();p.add_argument('stage',choices=['hts','diagnose']);p.add_argument('--job',required=True);a=p.parse_args()\\n    hts(a.job) if a.stage=='hts' else diagnosis(a.job)\\nif __name__=='__main__':main()\\n\",\"analysis.py\":\"\\\"\\\"\\\"既存固定支持の源励振・欠測・未知を全分母で閉じる。\\\"\\\"\\\"\\nfrom paths import *\\nimport argparse,subprocess\\nfrom collections import Counter\\ndef verify():\\n    c=read(HERE/'execution-contract.json')\\n    for n,h in c['sources'].items():assert digest(HERE/n)==h,n\\n    for n,h in c['inputs'].items():assert digest(REPO/n)==h,n\\n    assert digest(HERE/'registration.json')==c['registration_sha256'] and digest(HERE/'protocol.json')==c['protocol_sha256']\\ndef run(stage):\\n    verify();b=Budget();b.recover();records=read(HERE/'protocol.json')['records']\\n    if stage=='hts':\\n        number=sum(x['cohort']=='nas-vocoder-f0' and x['method'].startswith('hts') and not (HERE/'new-hts-diagnostic'/(x['id']+'.json')).exists() for x in records)\\n        assert number>0\\n        with b.job(NAME,'dsp','96HTS位相/実パルスの不変検査',count=number*2,reserve_bytes=1000000):\\n            with b.job(NAME,'render','既存HTS96の観測再構成。波形保存なし',count=number,reserve_bytes=600000000) as j:\\n                with b.workspace(j,'HTS観測の外部専用cache') as (_,env):\\n                    subprocess.run([str(PYTHON),'-B',str(HERE/'worker.py'),stage,'--job',j],env=env,check=True,timeout=10800)\\n    else:\\n        number=sum(not (HERE/'diagnostic'/(x['id']+'.json')).exists() for x in records);assert number>0\\n        with b.job(NAME,'dsp','全固定支持・旧DIO・実パルス・3窓を照合',count=number*3,reserve_bytes=600000000) as j:\\n            with b.workspace(j,'固定支持照合の外部専用cache') as (_,env):\\n                subprocess.run([str(PYTHON),'-B',str(HERE/'worker.py'),stage,'--job',j],env=env,check=True,timeout=10800)\\n    print(b.reconcile(),flush=True)\\ndef close():\\n    verify();b=Budget();b.recover()\\n    with b.job(NAME,'audit','全分母・源不足/音響曖昧/未知・費用・封印',reserve_bytes=5000000) as j:\\n        rows=[]\\n        for x in read(HERE/'diagnostic-manifest.json')['rows']:\\n            assert digest(REPO/x['path'])==x['sha256'];rows.append(read(REPO/x['path']))\\n        assert len(rows)==992 and sum(x['actual_source_known'] for x in rows)==224\\n        groups={}\\n        for x in rows:groups.setdefault(x['cohort']+'/'+x['method'],[]).append(x)\\n        table={}\\n        for k,v in groups.items():\\n            intervals=[d for x in v for d in x['all_fixed_support_intervals']];missing=[d for d in intervals if d['old_fixed_support_missing']]\\n            table[k]=dict(files=len(v),known_source_files=sum(x['actual_source_known'] for x in v),\\n                fixed_support_intervals=len(intervals),missing_intervals=len(missing),\\n                all_source_states=dict(Counter(d['actual_source_state'] for d in intervals)),\\n                missing_source_states=dict(Counter(d['actual_source_state'] for d in missing)),\\n                missing_drive_states=dict(Counter(d['driving_state'] for d in missing)),\\n                missing_phones=dict(Counter(d['phone'] for d in missing)),\\n                missing_duration_ms=dict(Counter(str(d['duration_ms']) for d in missing)))\\n        cross=read(CROSS/'aggregate-summary.json')\\n        for k,v in table.items():\\n            cohort,method=k.split('/');old=cross['cohorts'][cohort+'-20261008-v1']['methods'][method]\\n            assert v['files']==old['expected'] and v['missing_phones']==old['missing_phone_counts']\\n        summary=dict(total=992,actual_HTS_source_known=224,WORLD_actual_source_unknown=768,all_fixed_support_kept=True,\\n            groups=table,old_DIO_support_exact=True,old_missing_counts_match_cross_factor_audit=True,\\n            acoustic_ambiguity_not_proven_tracker_failure=True,source_pulse_does_not_guarantee_final_periodic_energy=True,\\n            WORLD_unknown_not_imputed=True,no_old_qualification_change=True,\\n            quality_goal_completed=False,protected_confirmation_opened=False,observational_existing_corpus_only=True)\\n        b.save(HERE/'aggregate-summary.json',summary,j)\\n        c=b.snapshot()['campaigns'][NAME];b.save(HERE/'cost-audit.json',dict(campaign=c,new_HTS_observations=96,reused_HTS_observations=128,\\n            new_WORLD_observations=0,new_AI=0,new_tracker_calls=0,all_temporary_removed=True),j)\\n        lines=['# 固定有声支持と実励振の欠測診断','',\\n            '既存992件の固定支持区間をすべて保持し、旧DIOのclock・有声件数・支持欠測を再照合した。WORLD768件は互換不通過のため実励振unknownを保持。HTS224件は旧128traceと、旧WAV完全一致の追加96traceを使用した。','',\\n            '|コホート/方式|支持区間|欠測|欠測源区分|','|---|---:|---:|---|']\\n        for k,v in table.items():lines.append(f\\\"|{k}|{v['fixed_support_intervals']}|{v['missing_intervals']}|{v['missing_source_states']}|\\\")\\n        lines+=['','源が全無声、区間内パルス0、4パルス未満、パルス存在下の音響曖昧、WORLD未確認を分けた。4パルス条件は第25回の窓内平均発生率に必要な3完全間隔であり、旧支持や知覚ゲートを変えていない。',\\n            'パルスがあってもLPF後の周期エネルギー・SNR・残響・非定常性の影響が残るため、DIOの欠測を測定器の失敗だけに断定しない。無励振区間の残響も保持する。源LF0の全有声は実励振truthではない。',\\n            '短窓/動的測定と源区分は事後診断に限定。旧ASR/採否/P5を更新しない。次は全結果と二ASR悪化群を統合し、追加制御比較の可否と必要条件を判断する。','']\\n        b.write(HERE/'report.md','\\\\n'.join(lines).encode(),j)\\n        files={str(p.relative_to(REPO)):digest(p) for p in HERE.rglob('*') if p.is_file()}\\n        b.save(HERE/'artifact-seal.json',dict(files=files,path_base='repository',experiment_completed=True,quality_goal_completed=False,protected_confirmation_opened=False),j)\\n        b.save(HERE/'completion-audit.json',dict(files_verified=len(files),seal_sha256=digest(HERE/'artifact-seal.json'),all_temporary_removed=True),j)\\n    b.close_campaign(NAME)\\n    with b.locked():\\n        s=b._load();s.setdefault('continuation_checkpoint_history',[]).append(s['continuation_checkpoint'])\\n        s['continuation_checkpoint']=dict(id='support-excitation-completed-20261008-0001',active_campaign=None,campaign_closed=True,\\n            next='commit/push→第28回全結果/ASR悪化群/終了監査',git_save_pending=True,quality_goal_completed=False,protected_confirmation_opened=False);b._write_state(s)\\n    b.save(ROOT/'progress-0039.json',dict(latest_completed=NAME,quality_goal_completed=False,next='第28回統合終了監査',budget=b.reconcile()))\\n    print(b.reconcile(),flush=True)\\ndef main():\\n    p=argparse.ArgumentParser();p.add_argument('stage',choices=['hts','diagnose','close']);a=p.parse_args()\\n    close() if a.stage=='close' else run(a.stage)\\nif __name__=='__main__':main()\\n\"}")
def main():
    b=Budget();b.recover();s=b.snapshot()
    assert not s['jobs'] and len(s['campaigns'])==26 and all(c['closed'] for c in s['campaigns'].values())
    assert s['limits']['seconds']-s['seconds']-14400>=14400
    assert shutil.disk_usage(ROOT).free>=20000000000 and shutil.disk_usage(b.guard.root).free>=4000000000
    cohorts=['nas-absolute-f0','nas-voicing-ap','nas-vocoder-f0','nas-mcp-postfilter','nas-gv-ablation','nas-gv-ap-interaction']
    inputs={str(p.relative_to(REPO)):digest(p) for p in [PREVIOUS/'artifact-seal.json',PREVIOUS/'aggregate-summary.json',PERIOD/'artifact-seal.json',PERIOD/'diagnostic-manifest.json',PERIOD/'runtime-bundle/manifest.json',WINDOW/'artifact-seal.json',WINDOW/'analysis.py',CROSS/'artifact-seal.json',CROSS/'aggregate-summary.json',ROOT/'campaign-allocation-approval-20261008-0001.json']}
    records=[]
    for prefix in cohorts:
        d=ROOT/'campaigns'/(prefix+'-20261008-v1');p=read(d/'protocol.json');seal=read(d/'artifact-seal.json')['files']
        inputs[str((d/'protocol.json').relative_to(REPO))]=digest(d/'protocol.json')
        inputs[str((d/'artifact-seal.json').relative_to(REPO))]=digest(d/'artifact-seal.json')
        for row in p['rows']:
            for condition in p['conditions']:
                fixed=None
                for method in p['variants']:
                    record=d/'render'/row['id']/condition/(method+'.json');x=read(record);params=record.with_suffix('.npz');dio=record.with_suffix('.dio.npz');wave=REPO/x['wav']
                    assert x['status']=='completed'
                    for path in [record,params,dio,wave]:assert digest(path)==seal[str(path.relative_to(REPO))],str(path)
                    if fixed is None:assert method=='native';fixed=x['measurement']['support']
                    assert x['measurement']['support']==fixed
                    records.append(dict(id=prefix+'/'+row['id']+'/'+condition+'/'+method,cohort=prefix,row_id=row['id'],condition=condition,method=method,
                        record=str(record.relative_to(REPO)),record_sha256=digest(record),parameters=str(params.relative_to(REPO)),parameters_sha256=digest(params),
                        dio=str(dio.relative_to(REPO)),dio_sha256=digest(dio),wave=str(wave.relative_to(REPO)),wave_sha256=x['wav_sha256']))
    assert len(records)==992 and len({x['id'] for x in records})==992
    reg=dict(campaign=NAME,status='registered_before_output',
        question='旧固定有声支持の欠測は、確認できた源無声/パルス不足/パルス存在下の音響曖昧/源未確認にどの程度分かれるか。',
        existing_cases=992,existing_HTS_trace=128,extra_existing_HTS_observation=96,WORLD_actual_source_unknown=768,
        WORLD_qualification_nonpass_preserved=True,all_native_fixed_support_retained=True,
        source_categories=['WORLD_unknown_compatibility_nonpass','source_unvoiced','no_pulse_in_interval','fewer_than_four_pulses','pulse_present_acoustic_ambiguity'],
        source_pulse_minimum=4,reason='第25回の窓内平均発生率に3完全間隔が必要。旧支持の3frame/半数条件とは別の診断。',
        clocks='旧DIO5ms clockをそのまま使用。状態長の5状態/音素を固定し、再時刻合わせや支持選び直しをしない。',
        HTS_96_invariance='第22回の固定observerを再利用。β0/初回nativeMCP先行なしを旧第17回と一致させ、全96旧WAV bytehash一致必須。',
        pulse_not_guarantee_filtered_periodic_energy=True,absence_not_absence_of_filter_ringing=True,
        missing_with_pulses_not_proven_tracker_failure=True,LF0_not_actual_excitation=True,
        short_windows_ms=[20,40,60],window_GT_same_as_campaign25=True,old_DIO_reused=True,new_tracker_AI=0,
        no_new_synthesis_path=True,no_old_gate_decision_change=True,causal_perceptual_claim=False,
        protected_confirmation_opened=False,quality_goal_completed=False,
        limits=dict(seconds=14400,bytes=1500000000,render=300,dsp=10000,download=0,setup=50,audit=50,ai=0,teacher=0,train=0,inverse=0),
        estimates=dict(extra_render=96,conservative_DSP=3168,trace_outputs=350000000,metadata=20000000,temporary_peak=8000000,
            retry_storage=900000000,peak_total=1280000000),
        technical_retry_per_job=2,technical_retry_campaign=10,ram_gb=8,next='第28回全結果/二ASR悪化群統合と終了監査')
    SOURCES['temporary_storage.py']=(PREVIOUS/'temporary_storage.py').read_text().replace("owner = 'world-excitation-audit-'","owner = 'support-excitation-audit-'")
    original=(WINDOW/'analysis.py').read_text();node=next(n for n in ast.parse(original).body if isinstance(n,ast.FunctionDef) and n.name=='ground')
    SOURCES['pulse_ground.py']='"""第25回の純時計ground関数を変更せず使用する。"""\n'+ast.get_source_segment(original,node)+'\n'
    for n,x in SOURCES.items():ast.parse(x,filename=n)
    b.start_campaign(NAME,str(HERE.relative_to(ROOT)),reg['limits'],hashlib.sha256(encode(reg)).hexdigest())
    with b.job(NAME,'setup','全992入力・固定支持・源分類・予算を固定',reserve_bytes=3000000) as j:
        b.save(HERE/'registration.json',reg,j);b.save(HERE/'protocol.json',dict(records=records,cohorts=cohorts,registration_sha256=digest(HERE/'registration.json')),j)
        for n,x in SOURCES.items():b.write(HERE/n,x.encode(),j)
